def transform(grid):
    h, w = len(grid), len(grid[0])
    points = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
              if grid[r][c] != 0]
    if not points:
        return [row[:] for row in grid]

    directions = [
        lambda r, c: r,
        lambda r, c: c,
        lambda r, c: r - c,
        lambda r, c: r + c,
    ]

    candidates = []
    for key_fn in directions:
        groups = {}
        for r, c, color in points:
            groups.setdefault(key_fn(r, c), []).append(color)

        # Each marked stripe must be a single color.
        if any(len(set(colors)) != 1 for colors in groups.values()):
            continue

        period = len(groups)
        phases = {}
        consistent = True
        for k, colors in groups.items():
            phase = k % period
            color = colors[0]
            if phase in phases and phases[phase] != color:
                consistent = False
                break
            phases[phase] = color
        if not consistent:
            continue

        longest = max(len(colors) for colors in groups.values())
        candidates.append((longest, len(points), key_fn, period, phases))

    if not candidates:
        return [row[:] for row in grid]

    _, _, key_fn, period, phases = max(candidates, key=lambda x: (x[0], x[1]))

    # Repeat the known stripe colors by phase. If any phase is absent,
    # continue cyclically from the phases that are present.
    known_phases = sorted(phases)
    for phase in range(period):
        if phase not in phases:
            phases[phase] = phases[known_phases[phase % len(known_phases)]]

    return [[phases[key_fn(r, c) % period] for c in range(w)]
            for r in range(h)]
